[entities]
// The road down to Harrowmere and the wayside shrine.
Ð = exit map=harrowmere at=31,2,90 label=Return_to_Harrowmere model=road_gate yaw=90
Ñ = save_statue
T = torch radius=7
// The long bridge: vents in the lava lob bombs onto it; hounds and bowmen hold it.
V = magma_vent radius=18 every=3.6 on=_
Ä = magma_vent radius=18 every=4.2 phase=1.8 on=_
H = slag_hound
B = iron_bowman
J = flame_jet dir=s len=1 every=3.2
Þ = flame_jet dir=s len=1 every=3.2 phase=1.1
ß = flame_jet dir=s len=1 every=3.2 phase=2.2
E = embers
// The skyline over the front wall, no two towers alike: a smelter stack, a drum bastion, a second
// bastion and the great gatehouse closing the gaps above the passages, a tall spire, a lesser stack
// and a stubby beacon tower; the keep rises behind them, and molten iron pours into the moat.
Ë = smokestack height=18 on=^
Ê = bastion top=6 radius=2.2 on=^
É = bastion base=6.2 top=14 radius=2.6 on=.
È = gatehouse on=.
Ò = spire height=14 width=2.2 on=^
Ì = smokestack height=10 on=^
Ø = spire height=7 width=2.8 roof=flat on=^
Í = keep on=~
Î = lavafall top=22 spout=gargoyle on=_
G = gate lever=hold_gate
Ó = door model=iron
// The gatehouse: a shrine, and the winch that raises the main gate.
Ô = save_statue
Õ = lever id=hold_gate
Q = chest item=red_tonic count=2 gold=60 model=iron
Z = brazier radius=9
W = cinder_wisp
Ö = door key=forge_key model=iron on=+
// The foundry and the smelter pits below it.
F = forge_golem
X = chest item=scroll_thunder gold=40 model=iron
M = mimic model=iron
N = anvil
Y = chest item=forge_key gold=50 model=iron
U = chest item=red_tonic count=3 gold=90 model=iron
D = lift top=0 locked on=|
// The ashworks: a gauntlet of flame jets, and a forge with a false wall.
I = chest item=blue_moss count=3 gold=120 model=iron
Ù = secret_wall
Ç = chest item=stormbrand model=iron
// The rampart, and the tower stair up to the keep, where the gargoyles perch on its roof.
O = chest item=slagbreaker model=iron
Ü = chest item=scroll_motes gold=60 model=iron
S = exit map=cinder_keep at=25,22,180 label=Enter_the_keep model=keep_door boss=gargoyles_dead on=o
// Dressing: gargoyles carved for the fortress, barred windows lit by the forges within, and the
// clutter of the smiths; the road up is staked with warnings.
C = gargoyle_statue
L = gargoyle_statue pose=snarl
À = barred_window
Á = forge_hearth
Â = crucible
Ã = quench_trough
Å = tool_rack
Æ = ingot_pile
Ï = slag_heap
Ú = impaler
Û = rubble
Ý = bones
à = crate
á = barrel
â = candles
ã = banner
å = chains
// The great wall's crenellated walk, run along its top behind the skyline.
æ = battlement span=10 on=^
ç = battlement span=6 on=^
è = battlement span=7 on=^
é = battlement span=9 on=^
ê = battlement span=5 on=^
// Great windows high in the curtain wall's face, the fires of the halls behind them burning over the moat.
ë = great_window rise=13 on=_
